def ulgs_p_idx (m j : ℕ) : ℕ := 2 ^ m * (2 * j + 1) - 1

def ulgs_s_of (B p : ℕ) : ℕ :=
  1189 * (2 * padicValNat 2 (p + 1) + 1) * 2 ^ (60 * (B + 2) * (p + 1))

def ulgs_J (B r : ℕ) : ℕ × ℕ :=
  let p := r / 3
  let u := r % 3
  let s := ulgs_s_of B p
  if u = 0 then (2 * s, 2 * s + 1)
  else if u = 1 then (3 * s + 1, 3 * s + 2)
  else (6 * s + 2, 6 * s + 4)

